Object.assign(window.SB_FEED_BODY, {"pl-meadow":{"src":"act:meadow","route":"#/atlas/honey/meadow","cta":"Open the Meadow","title":"Act I · The Meadow","body":"11 stops on this road, from “The Champion's Routine — say, spell, say” to “Ask the Right Questions — be a word detective”."},"li-u1":{"src":"concept:0:concept","route":"#/stop/u1","cta":"Open this stop","title":"The Champion's Routine — say, spell, say","body":"Every champion spells the same way: SAY the word, SPELL it letter by letter, then SAY it again. Saying it first proves your ears heard right; saying it after proves your letters match the sound."},"lc-u1-0":{"src":"concept:0:cards:0","route":"#/stop/u1","cta":"Open this stop","title":"The Champion's Routine — say, spell, say · The Core","body":"Champions never blurt letters. The routine is always the same three beats: SAY the word out loud, SPELL it at a steady pace, SAY it again. Say–spell–say. It works for a 4-letter word and a 14-letter word."},"lc-u1-1":{"src":"concept:0:cards:1","route":"#/stop/u1","cta":"Open this stop","title":"The Champion's Routine — say, spell, say · Why say it first?","body":"You cannot spell a word you heard wrong. Saying it back checks your ears: if the judge says 'remember' and you say 'remender', you just caught a mistake before it cost you. Your mouth is your first spell-checker."},"lc-u1-2":{"src":"concept:0:cards:2","route":"#/stop/u1","cta":"Open this stop","title":"The Champion's Routine — say, spell, say · Spell it steady","body":"Letters come out at a drumbeat — R…E…M…E…M…B…E…R — never in a rush. A steady beat keeps your place in the word, and at a real bee it lets the judges hear every letter clearly."},"lc-u1-3":{"src":"concept:0:cards:3","route":"#/stop/u1","cta":"Open this stop","title":"The Champion's Routine — say, spell, say · Why say it again?","body":"The final say seals the word. You just heard yourself spell it; saying the whole word confirms the letters you gave add up to the word you meant. If it feels wrong in your mouth, something was off."},"lc-u1-4":{"src":"concept:0:cards:4","route":"#/stop/u1","cta":"Open this stop","title":"The Champion's Routine — say, spell, say · Make it automatic","body":"Use the routine on every practice word in this app — easy ones too. When say–spell–say is a habit, your brain saves all its energy for the hard part: the letters."},"uq-u1-0":{"src":"unit:u1:qs:0","route":"#/stop/u1","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “The Champion's Routine — say, spell, say”?","opts":["Every champion spells the same way: SAY the word, SPELL it letter by letter, then SAY it again.","Old English/Latin un- = not (before adjectives) or reverse the action of (before verbs).","Latin com- = with, together.","The most common suffix in English — from Latin -tionem."],"after":"From “The Champion's Routine — say, spell, say”."}},"uq-u1-1":{"src":"unit:u1:qs:1","route":"#/stop/u1","cta":"Open this stop","title":"Which belongs?","play":{"q":"Which word belongs to this chapter's family?","opts":["remember","eloquent","unkempt","connoisseur"],"after":"From “The Champion's Routine — say, spell, say”."}},"uq-u1-3":{"src":"unit:u1:qs:3","route":"#/stop/u1","cta":"Open this stop","title":"Whose hook?","play":{"q":"“re + MEM + ber — the MEM in the middle comes from memory.” — which word is this hook about?","opts":["remember","practice","together","important"],"after":"From “The Champion's Routine — say, spell, say”."}},"wd-remember":{"src":"concept:0:words:0:def","route":"#/word/remember","cta":"Open the word card","title":"remember","roman":"rih-MEM-ber","body":"to keep something in your mind; to not forget","clip":1},"wx-remember":{"src":"concept:0:words:0:ex","route":"#/word/remember","cta":"Open the word card","title":"In a sentence · remember","body":"I remember the first word I ever spelled on stage.","clip":1},"wh-remember":{"src":"concept:0:words:0:hook","route":"#/word/remember","cta":"Open the word card","title":"Remember it · remember","body":"re + MEM + ber — the MEM in the middle comes from memory."},"wo-remember":{"src":"lore:remember:0","route":"#/word/remember","cta":"Open the word card","title":"Where it comes from · remember","body":"Latin rememorari = to call to mind"},"wd-practice":{"src":"concept:0:words:1:def","route":"#/word/practice","cta":"Open the word card","title":"practice","roman":"PRAK-tis","body":"to do something again and again to get better at it","clip":1},"wx-practice":{"src":"concept:0:words:1:ex","route":"#/word/practice","cta":"Open the word card","title":"In a sentence · practice","body":"She spends ten minutes on spelling practice every morning.","clip":1},"wh-practice":{"src":"concept:0:words:1:hook","route":"#/word/practice","cta":"Open the word card","title":"Remember it · practice","body":"PRACT + ICE — practice makes the tricky parts feel like smooth ice."},"wo-practice":{"src":"lore:practice:0","route":"#/word/practice","cta":"Open the word card","title":"Where it comes from · practice","body":"Greek 'praktike' from 'prassein' = to do"},"wd-together":{"src":"concept:0:words:2:def","route":"#/word/together","cta":"Open the word card","title":"together","roman":"tuh-GEH-ther","body":"with each other; joined as one group","clip":1},"wx-together":{"src":"concept:0:words:2:ex","route":"#/word/together","cta":"Open the word card","title":"In a sentence · together","body":"The team spelled the word together on the bus ride home.","clip":1},"wh-together":{"src":"concept:0:words:2:hook","route":"#/word/together","cta":"Open the word card","title":"Remember it · together","body":"to + get + her — three little words hiding inside one."},"wd-important":{"src":"concept:0:words:3:def","route":"#/word/important","cta":"Open the word card","title":"important","roman":"im-POR-tunt","body":"mattering a lot; having great value","clip":1},"wx-important":{"src":"concept:0:words:3:ex","route":"#/word/important","cta":"Open the word card","title":"In a sentence · important","body":"Remembering your kit is important if you want to play in the match.","clip":1},"wh-important":{"src":"concept:0:words:3:hook","route":"#/word/important","cta":"Open the word card","title":"Remember it · important","body":"im + PORT + ant — ends in -ANT, like an important ant carrying the word."},"wo-important":{"src":"lore:important:0","route":"#/word/important","cta":"Open the word card","title":"Where it comes from · important","body":"Latin importare = to bring in, be of consequence"},"wd-champion":{"src":"concept:0:words:4:def","route":"#/word/champion","cta":"Open the word card","title":"champion","roman":"CHAM-pee-un","body":"the winner of a competition; the very best","clip":1},"wx-champion":{"src":"concept:0:words:4:ex","route":"#/word/champion","cta":"Open the word card","title":"In a sentence · champion","body":"The champion said every word clearly before spelling it.","clip":1},"wh-champion":{"src":"concept:0:words:4:hook","route":"#/word/champion","cta":"Open the word card","title":"Remember it · champion","body":"CHAMP + ION — a CHAMP never skips the routine."},"wo-champion":{"src":"lore:champion:0","route":"#/word/champion","cta":"Open the word card","title":"Where it comes from · champion","body":"Old French champion = fighter, from Latin campus = field of battle"},"wd-microphone":{"src":"concept:0:words:5:def","route":"#/word/microphone","cta":"Open the word card","title":"microphone","roman":"MY-kruh-fohn","body":"a device that makes your voice louder","clip":1},"wx-microphone":{"src":"concept:0:words:5:ex","route":"#/word/microphone","cta":"Open the word card","title":"In a sentence · microphone","body":"Step up to the microphone and say the word first.","clip":1},"wh-microphone":{"src":"concept:0:words:5:hook","route":"#/word/microphone","cta":"Open the word card","title":"Remember it · microphone","body":"micro (small) + phone (sound) — a small-sound helper. PH says /f/."},"wo-microphone":{"src":"lore:microphone:0","route":"#/word/microphone","cta":"Open the word card","title":"Where it comes from · microphone","body":"Greek mikros=small + phone=voice/sound"},"wd-routine":{"src":"concept:0:words:6:def","route":"#/word/routine","cta":"Open the word card","title":"routine","roman":"roo-TEEN","body":"a set of steps done the same way every time","clip":1},"wx-routine":{"src":"concept:0:words:6:ex","route":"#/word/routine","cta":"Open the word card","title":"In a sentence · routine","body":"Her routine never changes: say it, spell it, say it again.","clip":1},"wh-routine":{"src":"concept:0:words:6:hook","route":"#/word/routine","cta":"Open the word card","title":"Remember it · routine","body":"rout + INE — the machine-like -INE ending, like engine."},"wo-routine":{"src":"lore:routine:0","route":"#/word/routine","cta":"Open the word card","title":"Where it comes from · routine","body":"French route = road, path"},"wd-steady":{"src":"concept:0:words:7:def","route":"#/word/steady","cta":"Open the word card","title":"steady","roman":"STEH-dee","body":"even and regular; not shaky or rushed","clip":1},"wx-steady":{"src":"concept:0:words:7:ex","route":"#/word/steady","cta":"Open the word card","title":"In a sentence · steady","body":"He spelled the letters at a slow, steady beat.","clip":1},"wh-steady":{"src":"concept:0:words:7:hook","route":"#/word/steady","cta":"Open the word card","title":"Remember it · steady","body":"STEAD + Y — EA makes the short e sound, like in bread."},"wd-clearly":{"src":"concept:0:words:8:def","route":"#/word/clearly","cta":"Open the word card","title":"clearly","roman":"KLEER-lee","body":"in a way that is easy to hear or see","clip":1},"wx-clearly":{"src":"concept:0:words:8:ex","route":"#/word/clearly","cta":"Open the word card","title":"In a sentence · clearly","body":"Say every syllable clearly before you begin.","clip":1},"wh-clearly":{"src":"concept:0:words:8:hook","route":"#/word/clearly","cta":"Open the word card","title":"Remember it · clearly","body":"CLEAR + LY — just add -ly to clear; no letters change."},"wd-confirm":{"src":"concept:0:words:9:def","route":"#/word/confirm","cta":"Open the word card","title":"confirm","roman":"kun-FURM","body":"to check that something is true or correct","clip":1},"wx-confirm":{"src":"concept:0:words:9:ex","route":"#/word/confirm","cta":"Open the word card","title":"In a sentence · confirm","body":"Saying the word again helps you confirm your spelling.","clip":1},"wh-confirm":{"src":"concept:0:words:9:hook","route":"#/word/confirm","cta":"Open the word card","title":"Remember it · confirm","body":"con + FIRM — make the word FIRM by saying it one more time."},"li-u2":{"src":"concept:1:concept","route":"#/stop/u2","cta":"Open this stop","title":"Alphabet Sounds — cat, city, goat, giant","body":"Letters are not their names: B says /b/, not 'bee'. Most letters keep one sound, but c and g each have two — hard before a, o, u and soft before e, i, y. Know what each letter SAYS and you can catch its sound in any word."},"lc-u2-0":{"src":"concept:1:cards:0","route":"#/stop/u2","cta":"Open this stop","title":"Alphabet Sounds — cat, city, goat, giant · The Core","body":"A letter's name and a letter's sound are different things. The letter B is named 'bee' but it says /b/, as in bat. When you spell by sound, always think about what the letter SAYS, never what it is called."},"lc-u2-1":{"src":"concept:1:cards:1","route":"#/stop/u2","cta":"Open this stop","title":"Alphabet Sounds — cat, city, goat, giant · Two faces of c","body":"C is a copycat with two voices. Before a, o, u it is HARD and says /k/: cat, coat, cup. Before e, i, y it is SOFT and says /s/: city, cent, cycle. The next letter decides — look one letter ahead."},"lc-u2-2":{"src":"concept:1:cards:2","route":"#/stop/u2","cta":"Open this stop","title":"Alphabet Sounds — cat, city, goat, giant · Two faces of g","body":"G plays the same game. Hard g before a, o, u: goat, game, gum. Soft g before e, i, y: giant, gentle, gym — it says /j/. (English keeps a few rebels like 'give' and 'girl', so listen first.)"},"lc-u2-3":{"src":"concept:1:cards:3","route":"#/stop/u2","cta":"Open this stop","title":"Alphabet Sounds — cat, city, goat, giant · The team players","body":"Q never works alone — it always brings u, and qu says /kw/: queen, quick, quiet. X is two sounds in one letter: /ks/, as in fox and exact. Spot them and you will never write 'qeen' or 'foks'."},"lc-u2-4":{"src":"concept:1:cards:4","route":"#/stop/u2","cta":"Open this stop","title":"Alphabet Sounds — cat, city, goat, giant · Use it at the mic","body":"When you hear /s/, ask: is it S, or a soft C? (city, not sity). When you hear /j/, ask: is it J, or a soft G? (giant, not jiant). The word's origin often decides — and you can ask for it at the bee!"},"uq-u2-0":{"src":"unit:u2:qs:0","route":"#/stop/u2","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “Alphabet Sounds — cat, city, goat, giant”?","opts":["Letters are not their names: B says /b/, not 'bee'.","Old English/Latin un- = not (before adjectives) or reverse the action of (before verbs).","Latin com- = with, together.","The most common suffix in English — from Latin -tionem."],"after":"From “Alphabet Sounds — cat, city, goat, giant”."}},"uq-u2-3":{"src":"unit:u2:qs:3","route":"#/stop/u2","cta":"Open this stop","title":"Whose hook?","play":{"q":"“Both c sounds in one word: soft CIR /s/, hard CUS /k/.” — which word is this hook about?","opts":["circus","city","cycle","giant"],"after":"From “Alphabet Sounds — cat, city, goat, giant”."}},"wd-circus":{"src":"concept:1:words:0:def","route":"#/word/circus","cta":"Open the word card","title":"circus","roman":"SUR-kus","body":"a traveling show with acrobats, clowns, and animals","clip":1},"wx-circus":{"src":"concept:1:words:0:ex","route":"#/word/circus","cta":"Open the word card","title":"In a sentence · circus","body":"The circus came to town with a big striped tent.","clip":1},"wh-circus":{"src":"concept:1:words:0:hook","route":"#/word/circus","cta":"Open the word card","title":"Remember it · circus","body":"Both c sounds in one word: soft CIR /s/, hard CUS /k/."},"wd-city":{"src":"concept:1:words:1:def","route":"#/word/city","cta":"Open the word card","title":"city","roman":"SIH-tee","body":"a large town where many people live","clip":1},"wx-city":{"src":"concept:1:words:1:ex","route":"#/word/city","cta":"Open the word card","title":"In a sentence · city","body":"The spelling bee finals were held in a big city.","clip":1},"wh-city":{"src":"concept:1:words:1:hook","route":"#/word/city","cta":"Open the word card","title":"Remember it · city","body":"Soft c before i — CITY starts with /s/ but is spelled with C."},"wd-cycle":{"src":"concept:1:words:2:def","route":"#/word/cycle","cta":"Open the word card","title":"cycle","roman":"SY-kul","body":"a set of events that repeats in the same order","clip":1},"wx-cycle":{"src":"concept:1:words:2:ex","route":"#/word/cycle","cta":"Open the word card","title":"In a sentence · cycle","body":"The seasons follow the same cycle every year.","clip":1},"wh-cycle":{"src":"concept:1:words:2:hook","route":"#/word/cycle","cta":"Open the word card","title":"Remember it · cycle","body":"Soft c before y, hard c before l — C-Y-C-L-E, one c soft, one hard."},"wd-giant":{"src":"concept:1:words:3:def","route":"#/word/giant","cta":"Open the word card","title":"giant","roman":"JY-unt","body":"a huge imaginary person; anything very large","clip":1},"wx-giant":{"src":"concept:1:words:3:ex","route":"#/word/giant","cta":"Open the word card","title":"In a sentence · giant","body":"A giant sequoia tree can grow taller than a building.","clip":1},"wh-giant":{"src":"concept:1:words:3:hook","route":"#/word/giant","cta":"Open the word card","title":"Remember it · giant","body":"Soft g before i — sounds like J but spelled GI."},"wo-giant":{"src":"lore:giant:0","route":"#/word/giant","cta":"Open the word card","title":"Where it comes from · giant","body":"Old French geant, from Latin gigas, from Greek gigas = giant"},"wd-gentle":{"src":"concept:1:words:4:def","route":"#/word/gentle","cta":"Open the word card","title":"gentle","roman":"JEN-tul","body":"kind and soft; not rough","clip":1},"wx-gentle":{"src":"concept:1:words:4:ex","route":"#/word/gentle","cta":"Open the word card","title":"In a sentence · gentle","body":"Be gentle when you turn the old book’s pages.","clip":1},"wh-gentle":{"src":"concept:1:words:4:hook","route":"#/word/gentle","cta":"Open the word card","title":"Remember it · gentle","body":"Soft g before e — GEN, not JEN."},"wd-garden":{"src":"concept:1:words:5:def","route":"#/word/garden","cta":"Open the word card","title":"garden","roman":"GAR-dun","body":"a piece of ground where flowers or vegetables grow","clip":1},"wx-garden":{"src":"concept:1:words:5:ex","route":"#/word/garden","cta":"Open the word card","title":"In a sentence · garden","body":"Grandma grows tomatoes in her back garden.","clip":1},"wh-garden":{"src":"concept:1:words:5:hook","route":"#/word/garden","cta":"Open the word card","title":"Remember it · garden","body":"Hard g before a — g keeps its true /g/ voice."},"wd-guitar":{"src":"concept:1:words:6:def","route":"#/word/guitar","cta":"Open the word card","title":"guitar","roman":"gih-TAR","body":"a musical instrument with six strings","clip":1},"wx-guitar":{"src":"concept:1:words:6:ex","route":"#/word/guitar","cta":"Open the word card","title":"In a sentence · guitar","body":"He practiced guitar after finishing his spelling words.","clip":1},"wh-guitar":{"src":"concept:1:words:6:hook","route":"#/word/guitar","cta":"Open the word card","title":"Remember it · guitar","body":"The u after g is a bodyguard keeping g hard — GUI, not GI."},"wo-guitar":{"src":"lore:guitar:0","route":"#/word/guitar","cta":"Open the word card","title":"Where it comes from · guitar","body":"Spanish guitarra, from Arabic qitar, from Greek kithara = lyre"},"wd-quick":{"src":"concept:1:words:7:def","route":"#/word/quick","cta":"Open the word card","title":"quick","roman":"KWIK","body":"fast; done in a short time","clip":1},"wx-quick":{"src":"concept:1:words:7:ex","route":"#/word/quick","cta":"Open the word card","title":"In a sentence · quick","body":"She gave a quick smile and spelled the word perfectly.","clip":1},"wh-quick":{"src":"concept:1:words:7:hook","route":"#/word/quick","cta":"Open the word card","title":"Remember it · quick","body":"Q always brings U — QU says /kw/."},"wd-queen":{"src":"concept:1:words:8:def","route":"#/word/queen","cta":"Open the word card","title":"queen","roman":"KWEEN","body":"a woman who rules a country","clip":1},"wx-queen":{"src":"concept:1:words:8:ex","route":"#/word/queen","cta":"Open the word card","title":"In a sentence · queen","body":"The queen bee is the mother of the whole hive.","clip":1},"wh-queen":{"src":"concept:1:words:8:hook","route":"#/word/queen","cta":"Open the word card","title":"Remember it · queen","body":"QU + EEN — never write q without its friend u."},"wd-expect":{"src":"concept:1:words:9:def","route":"#/word/expect","cta":"Open the word card","title":"expect","roman":"ek-SPEKT","body":"to think something will happen","clip":1},"wx-expect":{"src":"concept:1:words:9:ex","route":"#/word/expect","cta":"Open the word card","title":"In a sentence · expect","body":"I expect the next word will be harder than the last.","clip":1},"wh-expect":{"src":"concept:1:words:9:hook","route":"#/word/expect","cta":"Open the word card","title":"Remember it · expect","body":"X = /ks/ — one letter, two sounds: e/ks/pect."},"wo-expect":{"src":"lore:expect:0","route":"#/word/expect","cta":"Open the word card","title":"Where it comes from · expect","body":"Latin exspectare (to look out for), from ex- + spectare (to look)."},"li-u3":{"src":"concept:2:concept","route":"#/stop/u3","cta":"Open this stop","title":"Vowels & Magic E — cap, cape","body":"A, e, i, o, u each have a short voice (cap, pet, sit, hop, cub) and a long voice that says the letter's own name (cape, Pete, kite, hope, cube). A silent e at the end is the magic switch that turns the short voice long."},"lc-u3-0":{"src":"concept:2:cards:0","route":"#/stop/u3","cta":"Open this stop","title":"Vowels & Magic E — cap, cape · The Core","body":"Every vowel has two voices. The SHORT voice is quick: a as in cap, e as in pet, i as in sit, o as in hop, u as in cub. The LONG voice simply says the letter's name: cape, Pete, kite, hope, cube."},"lc-u3-1":{"src":"concept:2:cards:1","route":"#/stop/u3","cta":"Open this stop","title":"Vowels & Magic E — cap, cape · The magic e","body":"Add a silent e to the end and the vowel before it goes long: cap→cape, kit→kite, hop→hope, cub→cube, plan→plane. The e itself says nothing — it reaches back over one consonant and flips the switch."},"lc-u3-2":{"src":"concept:2:cards:2","route":"#/stop/u3","cta":"Open this stop","title":"Vowels & Magic E — cap, cape · Closed = short","body":"When a consonant closes in a vowel with no magic e, the vowel stays short: cat, bed, fish, pond, drum. One vowel, shut in by consonants — expect the short sound. This is the most common syllable in English."},"lc-u3-3":{"src":"concept:2:cards:3","route":"#/stop/u3","cta":"Open this stop","title":"Vowels & Magic E — cap, cape · Open = long","body":"When a syllable ENDS on its vowel, the vowel is free to say its name: go, me, hi, ba·by, mu·sic, pa·per. Spot where the syllable ends and you can predict the vowel sound before you spell it."},"lc-u3-4":{"src":"concept:2:cards:4","route":"#/stop/u3","cta":"Open this stop","title":"Vowels & Magic E — cap, cape · Y the substitute","body":"Y jumps in as a vowel when a, e, i, o, u are missing: gym (short i sound), sky (long i), happy (long e). If you hear a vowel sound but see no vowel, look for y doing the job."},"uq-u3-0":{"src":"unit:u3:qs:0","route":"#/stop/u3","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “Vowels & Magic E — cap, cape”?","opts":["A, e, i, o, u each have a short voice (cap, pet, sit, hop, cub) and a long voice that says the letter's own name (cape, Pete, kite, hope, cube).","Old English/Latin un- = not (before adjectives) or reverse the action of (before verbs).","Latin com- = with, together.","The most common suffix in English — from Latin -tionem."],"after":"From “Vowels & Magic E — cap, cape”."}},"uq-u3-3":{"src":"unit:u3:qs:3","route":"#/stop/u3","cta":"Open this stop","title":"Whose hook?","play":{"q":"“Magic e turns TAK into TAKE — the a says its name.” — which word is this hook about?","opts":["mistake","escape","invite","alone"],"after":"From “Vowels & Magic E — cap, cape”."}},"wd-mistake":{"src":"concept:2:words:0:def","route":"#/word/mistake","cta":"Open the word card","title":"mistake","roman":"mih-STAYK","body":"something done wrong; an error","clip":1},"wx-mistake":{"src":"concept:2:words:0:ex","route":"#/word/mistake","cta":"Open the word card","title":"In a sentence · mistake","body":"One small mistake taught her to slow down and say the word first.","clip":1},"wh-mistake":{"src":"concept:2:words:0:hook","route":"#/word/mistake","cta":"Open the word card","title":"Remember it · mistake","body":"Magic e turns TAK into TAKE — the a says its name."},"wd-escape":{"src":"concept:2:words:1:def","route":"#/word/escape","cta":"Open the word card","title":"escape","roman":"eh-SKAYP","body":"to get away from a place or danger","clip":1},"wx-escape":{"src":"concept:2:words:1:ex","route":"#/word/escape","cta":"Open the word card","title":"In a sentence · escape","body":"The hamster tried to escape from its cage again.","clip":1},"wh-escape":{"src":"concept:2:words:1:hook","route":"#/word/escape","cta":"Open the word card","title":"Remember it · escape","body":"ES + CAPE — magic e makes cap into cape."},"wd-invite":{"src":"concept:2:words:2:def","route":"#/word/invite","cta":"Open the word card","title":"invite","roman":"in-VYT","body":"to ask someone to come somewhere","clip":1},"wx-invite":{"src":"concept:2:words:2:ex","route":"#/word/invite","cta":"Open the word card","title":"In a sentence · invite","body":"Did you invite your cousins to the party?","clip":1},"wh-invite":{"src":"concept:2:words:2:hook","route":"#/word/invite","cta":"Open the word card","title":"Remember it · invite","body":"Magic e stretches VIT into VITE — long i."},"wd-alone":{"src":"concept:2:words:3:def","route":"#/word/alone","cta":"Open the word card","title":"alone","roman":"uh-LOHN","body":"without anyone else; by yourself","clip":1},"wx-alone":{"src":"concept:2:words:3:ex","route":"#/word/alone","cta":"Open the word card","title":"In a sentence · alone","body":"He likes to practice alone in his quiet room.","clip":1},"wh-alone":{"src":"concept:2:words:3:hook","route":"#/word/alone","cta":"Open the word card","title":"Remember it · alone","body":"A + LONE — magic e makes the o say its name."},"wd-complete":{"src":"concept:2:words:4:def","route":"#/word/complete","cta":"Open the word card","title":"complete","roman":"kum-PLEET","body":"having every part; finished","clip":1},"wx-complete":{"src":"concept:2:words:4:ex","route":"#/word/complete","cta":"Open the word card","title":"In a sentence · complete","body":"Complete the whole list before dinner.","clip":1},"wh-complete":{"src":"concept:2:words:4:hook","route":"#/word/complete","cta":"Open the word card","title":"Remember it · complete","body":"Magic e makes the middle e long — comPLETE."},"wd-costume":{"src":"concept:2:words:5:def","route":"#/word/costume","cta":"Open the word card","title":"costume","roman":"KOS-toom","body":"clothes worn to look like someone or something else","clip":1},"wx-costume":{"src":"concept:2:words:5:ex","route":"#/word/costume","cta":"Open the word card","title":"In a sentence · costume","body":"She wore a bee costume to the school parade.","clip":1},"wh-costume":{"src":"concept:2:words:5:hook","route":"#/word/costume","cta":"Open the word card","title":"Remember it · costume","body":"Magic e turns the u long: cos + TUME."},"wo-costume":{"src":"lore:costume:0","route":"#/word/costume","cta":"Open the word card","title":"Where it comes from · costume","body":"Italian costume = custom, habit, dress, from Latin consuetudo = custom"},"wd-baby":{"src":"concept:2:words:6:def","route":"#/word/baby","cta":"Open the word card","title":"baby","roman":"BAY-bee","body":"a very young child","clip":1},"wx-baby":{"src":"concept:2:words:6:ex","route":"#/word/baby","cta":"Open the word card","title":"In a sentence · baby","body":"The baby clapped every time someone spelled a word.","clip":1},"wh-baby":{"src":"concept:2:words:6:hook","route":"#/word/baby","cta":"Open the word card","title":"Remember it · baby","body":"Open syllable BA — the a is free, so it says its name."},"wd-music":{"src":"concept:2:words:7:def","route":"#/word/music","cta":"Open the word card","title":"music","roman":"MYOO-zik","body":"sounds arranged to be beautiful to hear","clip":1},"wx-music":{"src":"concept:2:words:7:ex","route":"#/word/music","cta":"Open the word card","title":"In a sentence · music","body":"Soft music helps him focus while studying.","clip":1},"wh-music":{"src":"concept:2:words:7:hook","route":"#/word/music","cta":"Open the word card","title":"Remember it · music","body":"Open MU = long u; closed SIC = short i."},"wd-gym":{"src":"concept:2:words:8:def","route":"#/word/gym","cta":"Open the word card","title":"gym","roman":"JIM","body":"a room or building for exercise and sports","clip":1},"wx-gym":{"src":"concept:2:words:8:ex","route":"#/word/gym","cta":"Open the word card","title":"In a sentence · gym","body":"The spelling bee was set up in the school gym.","clip":1},"wh-gym":{"src":"concept:2:words:8:hook","route":"#/word/gym","cta":"Open the word card","title":"Remember it · gym","body":"No a-e-i-o-u in sight — Y is the vowel, saying short i."},"wd-sky":{"src":"concept:2:words:9:def","route":"#/word/sky","cta":"Open the word card","title":"sky","roman":"SKY","body":"the space above the earth where clouds and stars appear","clip":1},"wx-sky":{"src":"concept:2:words:9:ex","route":"#/word/sky","cta":"Open the word card","title":"In a sentence · sky","body":"At dusk the sky turned deep orange, and the first bats flickered above the field.","clip":1},"wh-sky":{"src":"concept:2:words:9:hook","route":"#/word/sky","cta":"Open the word card","title":"Remember it · sky","body":"Y at the end of a little word says long i — s + k + y."},"li-u4":{"src":"concept:3:concept","route":"#/stop/u4","cta":"Open this stop","title":"Syllables — re, mem, ber","body":"A syllable is one beat of a word, and every beat has exactly one vowel sound. Long words are just short words holding hands: re·mem·ber is three easy pieces, not one scary one. Break the word into beats and spell one beat at a time."},"lc-u4-0":{"src":"concept:3:cards:0","route":"#/stop/u4","cta":"Open this stop","title":"Syllables — re, mem, ber · The Core","body":"Say 'remember' and clap: re–mem–ber. Three claps, three syllables, three small spelling jobs. A syllable is one push of your voice, and each push carries exactly one vowel sound."},"lc-u4-1":{"src":"concept:3:cards:1","route":"#/stop/u4","cta":"Open this stop","title":"Syllables — re, mem, ber · Find the beats","body":"Three easy ways to count beats: clap them, hum the word (each hum-bump is a beat), or rest your hand under your chin — your jaw drops once per syllable. Try 'umbrella': um–brel–la. Three drops."},"lc-u4-2":{"src":"concept:3:cards:2","route":"#/stop/u4","cta":"Open this stop","title":"Syllables — re, mem, ber · Twin consonants split","body":"When two of the same consonant sit in the middle, the syllables split between them: rab·bit, sum·mer, les·son. That's why the word keeps both letters — each syllable owns one. Hear rab + bit, write both b's."},"lc-u4-3":{"src":"concept:3:cards:3","route":"#/stop/u4","cta":"Open this stop","title":"Syllables — re, mem, ber · Spell beat by beat","body":"Never spell a long word in one gulp. Say the first syllable, spell it. Say the next, spell it. cal·en·dar = CAL + EN + DAR. Each piece is kid-sized, and the word spells itself."},"lc-u4-4":{"src":"concept:3:cards:4","route":"#/stop/u4","cta":"Open this stop","title":"Syllables — re, mem, ber · Every beat needs a vowel","body":"No syllable exists without a vowel sound — so if you spelled a syllable with no vowel letter, you dropped something. This one check catches missing-letter mistakes: cas-tle, lit-tle — the -le hides its vowel but always writes one."},"uq-u4-0":{"src":"unit:u4:qs:0","route":"#/stop/u4","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “Syllables — re, mem, ber”?","opts":["A syllable is one beat of a word, and every beat has exactly one vowel sound.","Old English/Latin un- = not (before adjectives) or reverse the action of (before verbs).","Latin com- = with, together.","The most common suffix in English — from Latin -tionem."],"after":"From “Syllables — re, mem, ber”."}},"uq-u4-3":{"src":"unit:u4:qs:3","route":"#/stop/u4","cta":"Open this stop","title":"Whose hook?","play":{"q":"“Three beats: fan + tas + tic — spell them one at a time.” — which word is this hook about?","opts":["fantastic","rabbit","summer","basket"],"after":"From “Syllables — re, mem, ber”."}},"wd-fantastic":{"src":"concept:3:words:0:def","route":"#/word/fantastic","cta":"Open the word card","title":"fantastic","roman":"fan-TAS-tik","body":"wonderful; extremely good","clip":1},"wx-fantastic":{"src":"concept:3:words:0:ex","route":"#/word/fantastic","cta":"Open the word card","title":"In a sentence · fantastic","body":"Spelling all ten words right feels fantastic.","clip":1},"wh-fantastic":{"src":"concept:3:words:0:hook","route":"#/word/fantastic","cta":"Open the word card","title":"Remember it · fantastic","body":"Three beats: fan + tas + tic — spell them one at a time."},"wo-fantastic":{"src":"lore:fantastic:0","route":"#/word/fantastic","cta":"Open the word card","title":"Where it comes from · fantastic","body":"Greek phantastikos = able to imagine"},"wd-rabbit":{"src":"concept:3:words:1:def","route":"#/word/rabbit","cta":"Open the word card","title":"rabbit","roman":"RAB-it","body":"a small animal with long ears that hops","clip":1},"wx-rabbit":{"src":"concept:3:words:1:ex","route":"#/word/rabbit","cta":"Open the word card","title":"In a sentence · rabbit","body":"A rabbit hopped across the garden path.","clip":1},"wh-rabbit":{"src":"concept:3:words:1:hook","route":"#/word/rabbit","cta":"Open the word card","title":"Remember it · rabbit","body":"Twin b’s split the beats: rab + bit — each syllable keeps one b."},"wd-summer":{"src":"concept:3:words:2:def","route":"#/word/summer","cta":"Open the word card","title":"summer","roman":"SUM-er","body":"the warmest season of the year","clip":1},"wx-summer":{"src":"concept:3:words:2:ex","route":"#/word/summer","cta":"Open the word card","title":"In a sentence · summer","body":"They practice spelling on the porch every summer evening.","clip":1},"wh-summer":{"src":"concept:3:words:2:hook","route":"#/word/summer","cta":"Open the word card","title":"Remember it · summer","body":"sum + mer — the twin m’s mark where the beats split."},"wd-basket":{"src":"concept:3:words:3:def","route":"#/word/basket","cta":"Open the word card","title":"basket","roman":"BAS-kit","body":"a container woven from strips, with a handle","clip":1},"wx-basket":{"src":"concept:3:words:3:ex","route":"#/word/basket","cta":"Open the word card","title":"In a sentence · basket","body":"She carried the word cards in a little basket.","clip":1},"wh-basket":{"src":"concept:3:words:3:hook","route":"#/word/basket","cta":"Open the word card","title":"Remember it · basket","body":"bas + ket — two closed beats, both vowels short."},"wd-monster":{"src":"concept:3:words:4:def","route":"#/word/monster","cta":"Open the word card","title":"monster","roman":"MON-ster","body":"a large frightening imaginary creature","clip":1},"wx-monster":{"src":"concept:3:words:4:ex","route":"#/word/monster","cta":"Open the word card","title":"In a sentence · monster","body":"Long words look like monsters until you break them into beats.","clip":1},"wh-monster":{"src":"concept:3:words:4:hook","route":"#/word/monster","cta":"Open the word card","title":"Remember it · monster","body":"mon + ster — two beats tame the monster."},"wd-umbrella":{"src":"concept:3:words:5:def","route":"#/word/umbrella","cta":"Open the word card","title":"umbrella","roman":"um-BREL-uh","body":"a folding cover that keeps rain off you","clip":1},"wx-umbrella":{"src":"concept:3:words:5:ex","route":"#/word/umbrella","cta":"Open the word card","title":"In a sentence · umbrella","body":"Keep an umbrella by the door in April.","clip":1},"wh-umbrella":{"src":"concept:3:words:5:hook","route":"#/word/umbrella","cta":"Open the word card","title":"Remember it · umbrella","body":"um + brel + la — three beats, twin l’s at the split."},"wo-umbrella":{"src":"lore:umbrella:0","route":"#/word/umbrella","cta":"Open the word card","title":"Where it comes from · umbrella","body":"Italian ombrella = little shade, from Latin umbra (shadow)"},"wd-wonderful":{"src":"concept:3:words:6:def","route":"#/word/wonderful","cta":"Open the word card","title":"wonderful","roman":"WUN-der-ful","body":"amazing; very good","clip":1},"wx-wonderful":{"src":"concept:3:words:6:ex","route":"#/word/wonderful","cta":"Open the word card","title":"In a sentence · wonderful","body":"The judges said her steady spelling was wonderful.","clip":1},"wh-wonderful":{"src":"concept:3:words:6:hook","route":"#/word/wonderful","cta":"Open the word card","title":"Remember it · wonderful","body":"won + der + ful — full loses an l when it becomes -ful."},"wd-hospital":{"src":"concept:3:words:7:def","route":"#/word/hospital","cta":"Open the word card","title":"hospital","roman":"HOS-pih-tul","body":"a place where sick or hurt people are cared for","clip":1},"wx-hospital":{"src":"concept:3:words:7:ex","route":"#/word/hospital","cta":"Open the word card","title":"In a sentence · hospital","body":"The hospital is two blocks from the school.","clip":1},"wh-hospital":{"src":"concept:3:words:7:hook","route":"#/word/hospital","cta":"Open the word card","title":"Remember it · hospital","body":"hos + pi + tal — three beats, spell each one alone."},"wo-hospital":{"src":"lore:hospital:0","route":"#/word/hospital","cta":"Open the word card","title":"Where it comes from · hospital","body":"Latin hospitale = inn for guests, from hospes = host"},"wd-calendar":{"src":"concept:3:words:8:def","route":"#/word/calendar","cta":"Open the word card","title":"calendar","roman":"KAL-un-der","body":"a chart of the days, weeks, and months of a year","clip":1},"wx-calendar":{"src":"concept:3:words:8:ex","route":"#/word/calendar","cta":"Open the word card","title":"In a sentence · calendar","body":"Circle the bee date on the kitchen calendar.","clip":1},"wh-calendar":{"src":"concept:3:words:8:hook","route":"#/word/calendar","cta":"Open the word card","title":"Remember it · calendar","body":"cal + en + dar — the last beat is DAR with an a, not der."},"wo-calendar":{"src":"lore:calendar:0","route":"#/word/calendar","cta":"Open the word card","title":"Where it comes from · calendar","body":"Latin calendarium = account book, from calendae = the first day of the month"},"wd-celebrate":{"src":"concept:3:words:9:def","route":"#/word/celebrate","cta":"Open the word card","title":"celebrate","roman":"SEL-uh-brayt","body":"to do something fun for a special occasion","clip":1},"wx-celebrate":{"src":"concept:3:words:9:ex","route":"#/word/celebrate","cta":"Open the word card","title":"In a sentence · celebrate","body":"We celebrate every level she finishes with pancakes.","clip":1},"wh-celebrate":{"src":"concept:3:words:9:hook","route":"#/word/celebrate","cta":"Open the word card","title":"Remember it · celebrate","body":"cel + e + brate — soft c starts it, magic e ends it."},"wo-celebrate":{"src":"lore:celebrate:0","route":"#/word/celebrate","cta":"Open the word card","title":"Where it comes from · celebrate","body":"Latin celebrare = to frequent, honor, make famous"},"li-u5":{"src":"concept:4:concept","route":"#/stop/u5","cta":"Open this stop","title":"Sounds to Letters — stretch, spell","body":"Inside each syllable live single sounds. Stretch the syllable like a rubber band — /s/…/t/…/a/…/m/…/p/ — and write each sound in the order you hear it. Nothing skipped, nothing guessed: that is spelling by sound."},"lc-u5-0":{"src":"concept:4:cards:0","route":"#/stop/u5","cta":"Open this stop","title":"Sounds to Letters — stretch, spell · The Core","body":"Take one syllable and stretch it slowly: 'stamp' becomes sss–t–aaa–mmm–p. Five sounds. Now write them in order: S, T, A, M, P. Every sound gets a letter; every letter earns its place."},"lc-u5-1":{"src":"concept:4:cards:1","route":"#/stop/u5","cta":"Open this stop","title":"Sounds to Letters — stretch, spell · Stretch like a band","body":"Say the word in slow motion, as if your voice were a rubber band being pulled. Sounds you rush past at normal speed — the n in 'plant', the r in 'crisp' — pop out clearly when stretched. What you can hear, you can spell."},"lc-u5-2":{"src":"concept:4:cards:2","route":"#/stop/u5","cta":"Open this stop","title":"Sounds to Letters — stretch, spell · Count first, then write","body":"Before writing, count the sounds on your fingers: /t/ /r/ /u/ /s/ /t/ — five. If your spelling has fewer letters than sounds, you dropped one. 'Trust' with four letters is missing something."},"lc-u5-3":{"src":"concept:4:cards:3","route":"#/stop/u5","cta":"Open this stop","title":"Sounds to Letters — stretch, spell · The order is the spelling","body":"Sounds come out in a line, and letters follow the same line. If you hear /d/ /r/ /i/ /f/ /t/, you write d-r-i-f-t. Swapping the order — 'dirft' — is the #1 slip, so touch a finger per sound as you write."},"lc-u5-4":{"src":"concept:4:cards:4","route":"#/stop/u5","cta":"Open this stop","title":"Sounds to Letters — stretch, spell · When teams join in","body":"Some sounds need two letters (sh, ch, th — next concept!), and some vowel sounds need teams too. But the stretch-and-spell habit stays the same: one sound at a time, in order, every sound accounted for."},"uq-u5-0":{"src":"unit:u5:qs:0","route":"#/stop/u5","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “Sounds to Letters — stretch, spell”?","opts":["Inside each syllable live single sounds.","Old English/Latin un- = not (before adjectives) or reverse the action of (before verbs).","Latin com- = with, together.","The most common suffix in English — from Latin -tionem."],"after":"From “Sounds to Letters — stretch, spell”."}},"uq-u5-3":{"src":"unit:u5:qs:3","route":"#/stop/u5","cta":"Open this stop","title":"Whose hook?","play":{"q":"“Stretch it: s-p-l-a-sh — five sounds, six letters.” — which word is this hook about?","opts":["splash","stamp","blend","crisp"],"after":"From “Sounds to Letters — stretch, spell”."}},"wd-splash":{"src":"concept:4:words:0:def","route":"#/word/splash","cta":"Open the word card","title":"splash","roman":"SPLASH","body":"to hit water so it flies around","clip":1},"wx-splash":{"src":"concept:4:words:0:ex","route":"#/word/splash","cta":"Open the word card","title":"In a sentence · splash","body":"The dog made a huge splash jumping into the pool.","clip":1},"wh-splash":{"src":"concept:4:words:0:hook","route":"#/word/splash","cta":"Open the word card","title":"Remember it · splash","body":"Stretch it: s-p-l-a-sh — five sounds, six letters."},"wd-stamp":{"src":"concept:4:words:1:def","route":"#/word/stamp","cta":"Open the word card","title":"stamp","roman":"STAMP","body":"a small paper square stuck on mail; to press your foot down","clip":1},"wx-stamp":{"src":"concept:4:words:1:ex","route":"#/word/stamp","cta":"Open the word card","title":"In a sentence · stamp","body":"Put a stamp on the envelope before mailing it.","clip":1},"wh-stamp":{"src":"concept:4:words:1:hook","route":"#/word/stamp","cta":"Open the word card","title":"Remember it · stamp","body":"s-t-a-m-p — do not lose the quiet m before p."},"wd-blend":{"src":"concept:4:words:2:def","route":"#/word/blend","cta":"Open the word card","title":"blend","roman":"BLEND","body":"to mix things together smoothly","clip":1},"wx-blend":{"src":"concept:4:words:2:ex","route":"#/word/blend","cta":"Open the word card","title":"In a sentence · blend","body":"Blend the letters together and read the word.","clip":1},"wh-blend":{"src":"concept:4:words:2:hook","route":"#/word/blend","cta":"Open the word card","title":"Remember it · blend","body":"b-l-e-n-d — the n hides before d; stretch to hear it."},"wd-crisp":{"src":"concept:4:words:3:def","route":"#/word/crisp","cta":"Open the word card","title":"crisp","roman":"KRISP","body":"firm and fresh; making a snapping sound","clip":1},"wx-crisp":{"src":"concept:4:words:3:ex","route":"#/word/crisp","cta":"Open the word card","title":"In a sentence · crisp","body":"The crisp autumn air smelled like leaves.","clip":1},"wh-crisp":{"src":"concept:4:words:3:hook","route":"#/word/crisp","cta":"Open the word card","title":"Remember it · crisp","body":"c-r-i-s-p — four consonants, one short i in the middle."},"wd-plant":{"src":"concept:4:words:4:def","route":"#/word/plant","cta":"Open the word card","title":"plant","roman":"PLANT","body":"a living thing that grows in soil","clip":1},"wx-plant":{"src":"concept:4:words:4:ex","route":"#/word/plant","cta":"Open the word card","title":"In a sentence · plant","body":"Water the plant twice a week.","clip":1},"wh-plant":{"src":"concept:4:words:4:hook","route":"#/word/plant","cta":"Open the word card","title":"Remember it · plant","body":"p-l-a-n-t — stretch it or the n vanishes."},"wd-drift":{"src":"concept:4:words:5:def","route":"#/word/drift","cta":"Open the word card","title":"drift","roman":"DRIFT","body":"to be carried slowly by water or air","clip":1},"wx-drift":{"src":"concept:4:words:5:ex","route":"#/word/drift","cta":"Open the word card","title":"In a sentence · drift","body":"The paper boat began to drift downstream.","clip":1},"wh-drift":{"src":"concept:4:words:5:hook","route":"#/word/drift","cta":"Open the word card","title":"Remember it · drift","body":"d-r-i-f-t — keep the order; dirft is the classic slip."},"wd-trust":{"src":"concept:4:words:6:def","route":"#/word/trust","cta":"Open the word card","title":"trust","roman":"TRUST","body":"to believe someone is honest and reliable","clip":1},"wx-trust":{"src":"concept:4:words:6:ex","route":"#/word/trust","cta":"Open the word card","title":"In a sentence · trust","body":"Trust your ears — they heard every sound.","clip":1},"wh-trust":{"src":"concept:4:words:6:hook","route":"#/word/trust","cta":"Open the word card","title":"Remember it · trust","body":"t-r-u-s-t — five sounds on five fingers."},"wd-twist":{"src":"concept:4:words:7:def","route":"#/word/twist","cta":"Open the word card","title":"twist","roman":"TWIST","body":"to turn something around and around","clip":1},"wx-twist":{"src":"concept:4:words:7:ex","route":"#/word/twist","cta":"Open the word card","title":"In a sentence · twist","body":"Twist the cap to open the bottle.","clip":1},"wh-twist":{"src":"concept:4:words:7:hook","route":"#/word/twist","cta":"Open the word card","title":"Remember it · twist","body":"t-w-i-s-t — the w is a real sound, not a decoration."},"wd-grasp":{"src":"concept:4:words:8:def","route":"#/word/grasp","cta":"Open the word card","title":"grasp","roman":"GRASP","body":"to grab firmly; to understand","clip":1},"wx-grasp":{"src":"concept:4:words:8:ex","route":"#/word/grasp","cta":"Open the word card","title":"In a sentence · grasp","body":"Once you grasp the method, long words feel easy.","clip":1},"wh-grasp":{"src":"concept:4:words:8:hook","route":"#/word/grasp","cta":"Open the word card","title":"Remember it · grasp","body":"g-r-a-s-p — stretch the end: sss then p."},"wd-strap":{"src":"concept:4:words:9:def","route":"#/word/strap","cta":"Open the word card","title":"strap","roman":"STRAP","body":"a strip of material used to fasten or hold things","clip":1},"wx-strap":{"src":"concept:4:words:9:ex","route":"#/word/strap","cta":"Open the word card","title":"In a sentence · strap","body":"Buckle the strap on your backpack.","clip":1},"wh-strap":{"src":"concept:4:words:9:hook","route":"#/word/strap","cta":"Open the word card","title":"Remember it · strap","body":"s-t-r-a-p — three consonants launch one short a."},"li-u6":{"src":"concept:5:concept","route":"#/stop/u6","cta":"Open this stop","title":"Letter Teams — sh, ch, th, ph","body":"Some sounds are spelled by two letters working as one team: sh in shark, ch in chest, th in thumb, wh in whale, ph in phone, ck in duck, ng in ring. One sound, two letters — spot the team and spell it as a unit."},"lc-u6-0":{"src":"concept:5:cards:0","route":"#/stop/u6","cta":"Open this stop","title":"Letter Teams — sh, ch, th, ph · The Core","body":"Stretch 'shark': /sh/–/ar/–/k/. That first sound is ONE sound, but no single letter says it — S and H team up. English is full of these letter teams; treat each team as a single spelling piece."},"lc-u6-1":{"src":"concept:5:cards:1","route":"#/stop/u6","cta":"Open this stop","title":"Letter Teams — sh, ch, th, ph · The big four","body":"SH as in shine and brush. CH as in chest and lunch. TH as in thumb and bath. WH as in whale and whisper. When you hear these sounds, your pencil writes two letters but your mind counts one."},"lc-u6-2":{"src":"concept:5:cards:2","route":"#/stop/u6","cta":"Open this stop","title":"Letter Teams — sh, ch, th, ph · Two kinds of th","body":"TH whispers in thin, thumb, math — and buzzes in this, that, brother. Put your fingers on your throat: the buzzing kind vibrates. Both are spelled the same way — T-H — so this trap costs nothing once you know it."},"lc-u6-3":{"src":"concept:5:cards:3","route":"#/stop/u6","cta":"Open this stop","title":"Letter Teams — sh, ch, th, ph · ch wears costumes","body":"CH usually says /ch/ (chest, lunch), but in Greek words it says /k/ — chorus, echo, school — and in French words it says /sh/ — chef, machine. If /k/ or /sh/ shows up in a fancy word, suspect CH and ask about the origin."},"lc-u6-4":{"src":"concept:5:cards:4","route":"#/stop/u6","cta":"Open this stop","title":"Letter Teams — sh, ch, th, ph · End-of-word teams","body":"CK ends short-vowel words: duck, clock, stick — never 'duk'. NG holds the ringing sound in ring, king, strong. PH is the Greek team for /f/: phone, graph, dolphin. Hear /f/ in a science-y word? Think PH."},"uq-u6-0":{"src":"unit:u6:qs:0","route":"#/stop/u6","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “Letter Teams — sh, ch, th, ph”?","opts":["Some sounds are spelled by two letters working as one team: sh in shark, ch in chest, th in thumb, wh in whale, ph in phone, ck in duck, ng in ring.","Old English/Latin un- = not (before adjectives) or reverse the action of (before verbs).","Latin com- = with, together.","The most common suffix in English — from Latin -tionem."],"after":"From “Letter Teams — sh, ch, th, ph”."}},"uq-u6-3":{"src":"unit:u6:qs:3","route":"#/stop/u6","cta":"Open this stop","title":"Whose hook?","play":{"q":"“WH team starts it — ▁▁▁, whale, what.” — which word is this hook about?","opts":["whisper","shark","chest","thumb"],"after":"From “Letter Teams — sh, ch, th, ph”."}},"wd-whisper":{"src":"concept:5:words:0:def","route":"#/word/whisper","cta":"Open the word card","title":"whisper","roman":"WIS-per","body":"to speak very softly and quietly","clip":1},"wx-whisper":{"src":"concept:5:words:0:ex","route":"#/word/whisper","cta":"Open the word card","title":"In a sentence · whisper","body":"She whispered the syllables to herself before spelling aloud.","clip":1},"wh-whisper":{"src":"concept:5:words:0:hook","route":"#/word/whisper","cta":"Open the word card","title":"Remember it · whisper","body":"WH team starts it — whisper, whale, what."},"wd-shark":{"src":"concept:5:words:1:def","route":"#/word/shark","cta":"Open the word card","title":"shark","roman":"SHARK","body":"a large ocean fish with sharp teeth","clip":1},"wx-shark":{"src":"concept:5:words:1:ex","route":"#/word/shark","cta":"Open the word card","title":"In a sentence · shark","body":"A shark can grow new teeth its whole life.","clip":1},"wh-shark":{"src":"concept:5:words:1:hook","route":"#/word/shark","cta":"Open the word card","title":"Remember it · shark","body":"SH is one sound, one team — sh + ark."},"wd-chest":{"src":"concept:5:words:2:def","route":"#/word/chest","cta":"Open the word card","title":"chest","roman":"CHEST","body":"the front of your body between neck and stomach; a big box","clip":1},"wx-chest":{"src":"concept:5:words:2:ex","route":"#/word/chest","cta":"Open the word card","title":"In a sentence · chest","body":"The pirate’s chest was full of gold coins.","clip":1},"wh-chest":{"src":"concept:5:words:2:hook","route":"#/word/chest","cta":"Open the word card","title":"Remember it · chest","body":"CH team + est — four sounds, five letters."},"wd-thumb":{"src":"concept:5:words:3:def","route":"#/word/thumb","cta":"Open the word card","title":"thumb","roman":"THUM","body":"the short thick finger on the side of your hand","clip":1},"wx-thumb":{"src":"concept:5:words:3:ex","route":"#/word/thumb","cta":"Open the word card","title":"In a sentence · thumb","body":"He gave a thumbs-up after spelling the word.","clip":1},"wh-thumb":{"src":"concept:5:words:3:hook","route":"#/word/thumb","cta":"Open the word card","title":"Remember it · thumb","body":"TH team starts it, silent b ends it — thum(b)."},"wd-whale":{"src":"concept:5:words:4:def","route":"#/word/whale","cta":"Open the word card","title":"whale","roman":"WAYL","body":"a huge animal that lives in the sea and breathes air","clip":1},"wx-whale":{"src":"concept:5:words:4:ex","route":"#/word/whale","cta":"Open the word card","title":"In a sentence · whale","body":"A blue whale’s heart is as big as a small car.","clip":1},"wh-whale":{"src":"concept:5:words:4:hook","route":"#/word/whale","cta":"Open the word card","title":"Remember it · whale","body":"WH + ALE — magic e makes the a long."},"wd-phone":{"src":"concept:5:words:5:def","route":"#/word/phone","cta":"Open the word card","title":"phone","roman":"FOHN","body":"a device used to talk to people far away","clip":1},"wx-phone":{"src":"concept:5:words:5:ex","route":"#/word/phone","cta":"Open the word card","title":"In a sentence · phone","body":"The good news came by phone that evening.","clip":1},"wh-phone":{"src":"concept:5:words:5:hook","route":"#/word/phone","cta":"Open the word card","title":"Remember it · phone","body":"PH is the Greek /f/ team — phone, photo, graph."},"wd-dolphin":{"src":"concept:5:words:6:def","route":"#/word/dolphin","cta":"Open the word card","title":"dolphin","roman":"DOL-fin","body":"a friendly sea animal that clicks and whistles","clip":1},"wx-dolphin":{"src":"concept:5:words:6:ex","route":"#/word/dolphin","cta":"Open the word card","title":"In a sentence · dolphin","body":"A dolphin leaped beside the boat.","clip":1},"wh-dolphin":{"src":"concept:5:words:6:hook","route":"#/word/dolphin","cta":"Open the word card","title":"Remember it · dolphin","body":"The /f/ in the middle is PH — dol + PHin."},"wo-dolphin":{"src":"lore:dolphin:0","route":"#/word/dolphin","cta":"Open the word card","title":"Where it comes from · dolphin","body":"Greek delphis = dolphin, related to delphus = womb"},"wd-kitchen":{"src":"concept:5:words:7:def","route":"#/word/kitchen","cta":"Open the word card","title":"kitchen","roman":"KIH-chin","body":"the room where food is cooked","clip":1},"wx-kitchen":{"src":"concept:5:words:7:ex","route":"#/word/kitchen","cta":"Open the word card","title":"In a sentence · kitchen","body":"The kitchen smelled like warm cookies.","clip":1},"wh-kitchen":{"src":"concept:5:words:7:hook","route":"#/word/kitchen","cta":"Open the word card","title":"Remember it · kitchen","body":"kit + CHen — TCH ch sound after a short vowel keeps the t."},"wd-string":{"src":"concept:5:words:8:def","route":"#/word/string","cta":"Open the word card","title":"string","roman":"STRING","body":"a thin rope for tying things","clip":1},"wx-string":{"src":"concept:5:words:8:ex","route":"#/word/string","cta":"Open the word card","title":"In a sentence · string","body":"Tie the balloons with a piece of string.","clip":1},"wh-string":{"src":"concept:5:words:8:hook","route":"#/word/string","cta":"Open the word card","title":"Remember it · string","body":"STR blend up front, NG team at the end."},"wd-clock":{"src":"concept:5:words:9:def","route":"#/word/clock","cta":"Open the word card","title":"clock","roman":"KLOK","body":"a machine that shows the time","clip":1},"wx-clock":{"src":"concept:5:words:9:ex","route":"#/word/clock","cta":"Open the word card","title":"In a sentence · clock","body":"Her eyes kept jumping to the clock during the test.","clip":1},"wh-clock":{"src":"concept:5:words:9:hook","route":"#/word/clock","cta":"Open the word card","title":"Remember it · clock","body":"Short o, so the /k/ ending is the CK team — never just k."},"li-u7":{"src":"concept:6:concept","route":"#/stop/u7","cta":"Open this stop","title":"Vowel Teams — ai, ay, ee, oa","body":"Long vowel sounds are usually spelled by two vowels teaming up: ai/ay for long a, ee/ea for long e, oa/ow for long o, oi/oy and au/aw for the twisty sounds. Position picks the team: ay, oy, ow like the END of words; ai, oi, oa work INSIDE."},"lc-u7-0":{"src":"concept:6:cards:0","route":"#/stop/u7","cta":"Open this stop","title":"Vowel Teams — ai, ay, ee, oa · The Core","body":"Hear the long a in 'paint'? No magic e in sight — instead two vowels team up: AI. Vowel teams are the second great way English spells long vowels, and each team has a favorite seat in the word."},"lc-u7-1":{"src":"concept:6:cards:1","route":"#/stop/u7","cta":"Open this stop","title":"Vowel Teams — ai, ay, ee, oa · The position rule","body":"Teams ending in Y or W love the END of a word: play, stay, boy, enjoy, snow, grow. Their twins work INSIDE: paint, rain, coin, point, coat, road. Same sound, different seat — pl-AY but p-AI-nt."},"lc-u7-2":{"src":"concept:6:cards:2","route":"#/stop/u7","cta":"Open this stop","title":"Vowel Teams — ai, ay, ee, oa · Long e twins","body":"EE and EA both say long e: sweet, green — and eat, reason, team. There is no perfect rule for choosing, so meet each word once and let the hook stick: you EAT a pEAch; you SEE a bEE. (EA sometimes goes short: bread, head.)"},"lc-u7-3":{"src":"concept:6:cards:3","route":"#/stop/u7","cta":"Open this stop","title":"Vowel Teams — ai, ay, ee, oa · The whiny sounds","body":"OI/OY is the 'annoyed' sound: coin, voice — boy, royal. OU/OW is the 'ouch' sound: loud, house — cow, tower. AU/AW is the 'awe' sound: author, because — saw, awesome. End of word? Pick the Y or W twin."},"lc-u7-4":{"src":"concept:6:cards:4","route":"#/stop/u7","cta":"Open this stop","title":"Vowel Teams — ai, ay, ee, oa · Spell the team, not letters","body":"When you stretch a word and hit a long vowel, do not write one letter — ask WHICH TEAM spells it here. r-ai-n. b-oa-t. pl-ay. The team is a single spelling piece, exactly like sh or ch."},"uq-u7-0":{"src":"unit:u7:qs:0","route":"#/stop/u7","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “Vowel Teams — ai, ay, ee, oa”?","opts":["Long vowel sounds are usually spelled by two vowels teaming up: ai/ay for long a, ee/ea for long e, oa/ow for long o, oi/oy and au/aw for the twisty sounds.","Old English/Latin un- = not (before adjectives) or reverse the action of (before verbs).","Latin com- = with, together.","The most common suffix in English — from Latin -tionem."],"after":"From “Vowel Teams — ai, ay, ee, oa”."}},"uq-u7-3":{"src":"unit:u7:qs:3","route":"#/stop/u7","cta":"Open this stop","title":"Whose hook?","play":{"q":"“AI inside, OW at the end — two teams, both in position.” — which word is this hook about?","opts":["rainbow","crayon","paint","sweet"],"after":"From “Vowel Teams — ai, ay, ee, oa”."}},"wd-rainbow":{"src":"concept:6:words:0:def","route":"#/word/rainbow","cta":"Open the word card","title":"rainbow","roman":"RAYN-boh","body":"an arch of colors in the sky after rain","clip":1},"wx-rainbow":{"src":"concept:6:words:0:ex","route":"#/word/rainbow","cta":"Open the word card","title":"In a sentence · rainbow","body":"A double rainbow stretched over the valley.","clip":1},"wh-rainbow":{"src":"concept:6:words:0:hook","route":"#/word/rainbow","cta":"Open the word card","title":"Remember it · rainbow","body":"AI inside, OW at the end — two teams, both in position."},"wo-rainbow":{"src":"lore:rainbow:0","route":"#/word/rainbow","cta":"Open the word card","title":"Where it comes from · rainbow","body":"Old English regnboga = rain + bow/arc"},"wd-crayon":{"src":"concept:6:words:1:def","route":"#/word/crayon","cta":"Open the word card","title":"crayon","roman":"KRAY-on","body":"a stick of colored wax for drawing","clip":1},"wx-crayon":{"src":"concept:6:words:1:ex","route":"#/word/crayon","cta":"Open the word card","title":"In a sentence · crayon","body":"She drew the bee with a yellow crayon.","clip":1},"wh-crayon":{"src":"concept:6:words:1:hook","route":"#/word/crayon","cta":"Open the word card","title":"Remember it · crayon","body":"AY ends its syllable: cray + on."},"wo-crayon":{"src":"lore:crayon:0","route":"#/word/crayon","cta":"Open the word card","title":"Where it comes from · crayon","body":"French craie = chalk, from Latin creta = chalk"},"wd-paint":{"src":"concept:6:words:2:def","route":"#/word/paint","cta":"Open the word card","title":"paint","roman":"PAYNT","body":"colored liquid you brush onto things","clip":1},"wx-paint":{"src":"concept:6:words:2:ex","route":"#/word/paint","cta":"Open the word card","title":"In a sentence · paint","body":"They used blue paint for the ocean poster.","clip":1},"wh-paint":{"src":"concept:6:words:2:hook","route":"#/word/paint","cta":"Open the word card","title":"Remember it · paint","body":"Long a inside the word = AI: p-ai-nt."},"wd-sweet":{"src":"concept:6:words:3:def","route":"#/word/sweet","cta":"Open the word card","title":"sweet","roman":"SWEET","body":"tasting like sugar; very pleasant","clip":1},"wx-sweet":{"src":"concept:6:words:3:ex","route":"#/word/sweet","cta":"Open the word card","title":"In a sentence · sweet","body":"Victory tasted sweet after all that practice.","clip":1},"wh-sweet":{"src":"concept:6:words:3:hook","route":"#/word/sweet","cta":"Open the word card","title":"Remember it · sweet","body":"EE in the middle — you SEE two e’s in sweet."},"wd-reason":{"src":"concept:6:words:4:def","route":"#/word/reason","cta":"Open the word card","title":"reason","roman":"REE-zun","body":"why something happens; a cause","clip":1},"wx-reason":{"src":"concept:6:words:4:ex","route":"#/word/reason","cta":"Open the word card","title":"In a sentence · reason","body":"There is a reason for every strange spelling.","clip":1},"wh-reason":{"src":"concept:6:words:4:hook","route":"#/word/reason","cta":"Open the word card","title":"Remember it · reason","body":"EA says long e: r-ea-son."},"wd-coast":{"src":"concept:6:words:5:def","route":"#/word/coast","cta":"Open the word card","title":"coast","roman":"KOHST","body":"the land along the edge of the sea","clip":1},"wx-coast":{"src":"concept:6:words:5:ex","route":"#/word/coast","cta":"Open the word card","title":"In a sentence · coast","body":"They drove down the coast to the finals.","clip":1},"wh-coast":{"src":"concept:6:words:5:hook","route":"#/word/coast","cta":"Open the word card","title":"Remember it · coast","body":"OA works inside: c-oa-st."},"wd-window":{"src":"concept:6:words:6:def","route":"#/word/window","cta":"Open the word card","title":"window","roman":"WIN-doh","body":"an opening in a wall filled with glass","clip":1},"wx-window":{"src":"concept:6:words:6:ex","route":"#/word/window","cta":"Open the word card","title":"In a sentence · window","body":"Morning light came through the classroom window.","clip":1},"wh-window":{"src":"concept:6:words:6:hook","route":"#/word/window","cta":"Open the word card","title":"Remember it · window","body":"OW takes the end seat: wind + ow."},"wd-voyage":{"src":"concept:6:words:7:def","route":"#/word/voyage","cta":"Open the word card","title":"voyage","roman":"VOY-ij","body":"a long journey by sea or through space","clip":1},"wx-voyage":{"src":"concept:6:words:7:ex","route":"#/word/voyage","cta":"Open the word card","title":"In a sentence · voyage","body":"The explorers began their voyage at dawn.","clip":1},"wh-voyage":{"src":"concept:6:words:7:hook","route":"#/word/voyage","cta":"Open the word card","title":"Remember it · voyage","body":"OY ends its syllable: voy + age."},"wd-poison":{"src":"concept:6:words:8:def","route":"#/word/poison","cta":"Open the word card","title":"poison","roman":"POY-zun","body":"something that can make you sick if swallowed","clip":1},"wx-poison":{"src":"concept:6:words:8:ex","route":"#/word/poison","cta":"Open the word card","title":"In a sentence · poison","body":"Some bright frogs carry poison on their skin.","clip":1},"wh-poison":{"src":"concept:6:words:8:hook","route":"#/word/poison","cta":"Open the word card","title":"Remember it · poison","body":"OI inside the word: p-oi-son."},"wd-author":{"src":"concept:6:words:9:def","route":"#/word/author","cta":"Open the word card","title":"author","roman":"AW-thur","body":"a person who writes books or stories","clip":1},"wx-author":{"src":"concept:6:words:9:ex","route":"#/word/author","cta":"Open the word card","title":"In a sentence · author","body":"The author signed her book for every kid in line.","clip":1},"wh-author":{"src":"concept:6:words:9:hook","route":"#/word/author","cta":"Open the word card","title":"Remember it · author","body":"AU inside: au + thor. (AW would end a word, like saw.)"},"li-u8":{"src":"concept:7:concept","route":"#/stop/u8","cta":"Open this stop","title":"Blends & Silent Letters — kn, wr, mb","body":"In a blend, every letter still speaks — st, str, spl: just spell what you hear, in order. Silent letters are the opposite: leftover letters from old English that went quiet — the k in knee, w in write, b in climb. Blends you hear; silents you remember."},"lc-u8-0":{"src":"concept:7:cards:0","route":"#/stop/u8","cta":"Open this stop","title":"Blends & Silent Letters — kn, wr, mb · The Core","body":"Two kinds of letter clusters, opposite rules. BLENDS: every letter sounds — /s//t/ in stop, /s//t//r/ in strong. Stretch and spell. SILENT LETTERS: a letter sits in the word saying nothing — knee starts with /n/ but writes KN."},"lc-u8-1":{"src":"concept:7:cards:1","route":"#/stop/u8","cta":"Open this stop","title":"Blends & Silent Letters — kn, wr, mb · Blends: trust your ears","body":"st, sp, sk, bl, cl, fr, gr, str, spl, scr — in all of these, each letter earns its sound. Stretch 'splash': /s/ /p/ /l/… every sound is there. Blends never need memorizing; they need careful ears."},"lc-u8-2":{"src":"concept:7:cards:2","route":"#/stop/u8","cta":"Open this stop","title":"Blends & Silent Letters — kn, wr, mb · Silents: little ghosts","body":"Hundreds of years ago, people really said the k in knee and the w in write. Speech moved on; spelling stayed. So the silent letters are ghosts of old pronunciations — invisible to your ears, required by your pencil."},"lc-u8-3":{"src":"concept:7:cards:3","route":"#/stop/u8","cta":"Open this stop","title":"Blends & Silent Letters — kn, wr, mb · The ghost families","body":"KN- says /n/: knee, knight, knock, know. WR- says /r/: write, wrist, wrong. -MB says /m/: climb, thumb, lamb, comb. Learn them as families and one memory covers a dozen words."},"lc-u8-4":{"src":"concept:7:cards:4","route":"#/stop/u8","cta":"Open this stop","title":"Blends & Silent Letters — kn, wr, mb · Which is it?","body":"Hear /n/ at the start? It might be N or KN. Hear /r/? Maybe WR. The meaning helps: writing words take WR (write, wrote); knowing-and-body words often take KN (know, knee, knuckle). At the bee, the definition question is your friend."},"uq-u8-0":{"src":"unit:u8:qs:0","route":"#/stop/u8","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “Blends & Silent Letters — kn, wr, mb”?","opts":["In a blend, every letter still speaks — st, str, spl: just spell what you hear, in order.","Old English/Latin un- = not (before adjectives) or reverse the action of (before verbs).","Latin com- = with, together.","The most common suffix in English — from Latin -tionem."],"after":"From “Blends & Silent Letters — kn, wr, mb”."}},"uq-u8-3":{"src":"unit:u8:qs:3","route":"#/stop/u8","cta":"Open this stop","title":"Whose hook?","play":{"q":"“Silent k, silent gh — six letters, three sounds.” — which word is this hook about?","opts":["knight","knee","knock","write"],"after":"From “Blends & Silent Letters — kn, wr, mb”."}},"wd-knight":{"src":"concept:7:words:0:def","route":"#/word/knight","cta":"Open the word card","title":"knight","roman":"NYT","body":"a warrior in armor who served a king","clip":1},"wx-knight":{"src":"concept:7:words:0:ex","route":"#/word/knight","cta":"Open the word card","title":"In a sentence · knight","body":"The knight bowed before the queen.","clip":1},"wh-knight":{"src":"concept:7:words:0:hook","route":"#/word/knight","cta":"Open the word card","title":"Remember it · knight","body":"Silent k, silent gh — six letters, three sounds."},"wo-knight":{"src":"lore:knight:0","route":"#/word/knight","cta":"Open the word card","title":"Where it comes from · knight","body":"Old English cniht = boy/servant/military follower"},"wd-knee":{"src":"concept:7:words:1:def","route":"#/word/knee","cta":"Open the word card","title":"knee","roman":"NEE","body":"the joint in the middle of your leg","clip":1},"wx-knee":{"src":"concept:7:words:1:ex","route":"#/word/knee","cta":"Open the word card","title":"In a sentence · knee","body":"She scraped her knee on the playground.","clip":1},"wh-knee":{"src":"concept:7:words:1:hook","route":"#/word/knee","cta":"Open the word card","title":"Remember it · knee","body":"KN family — the k is a ghost from old English."},"wd-knock":{"src":"concept:7:words:2:def","route":"#/word/knock","cta":"Open the word card","title":"knock","roman":"NOK","body":"to hit a door to be let in","clip":1},"wx-knock":{"src":"concept:7:words:2:ex","route":"#/word/knock","cta":"Open the word card","title":"In a sentence · knock","body":"Knock twice before you come in.","clip":1},"wh-knock":{"src":"concept:7:words:2:hook","route":"#/word/knock","cta":"Open the word card","title":"Remember it · knock","body":"Ghost k up front, CK team at the back."},"wd-write":{"src":"concept:7:words:3:def","route":"#/word/write","cta":"Open the word card","title":"write","roman":"RYT","body":"to make letters and words on paper","clip":1},"wx-write":{"src":"concept:7:words:3:ex","route":"#/word/write","cta":"Open the word card","title":"In a sentence · write","body":"Write each word three times to lock it in.","clip":1},"wh-write":{"src":"concept:7:words:3:hook","route":"#/word/write","cta":"Open the word card","title":"Remember it · write","body":"WR family — writing words keep the silent w."},"wd-wrist":{"src":"concept:7:words:4:def","route":"#/word/wrist","cta":"Open the word card","title":"wrist","roman":"RIST","body":"the joint between your hand and arm","clip":1},"wx-wrist":{"src":"concept:7:words:4:ex","route":"#/word/wrist","cta":"Open the word card","title":"In a sentence · wrist","body":"He wore his lucky band around his wrist.","clip":1},"wh-wrist":{"src":"concept:7:words:4:hook","route":"#/word/wrist","cta":"Open the word card","title":"Remember it · wrist","body":"WR + ist — silent w, then a clean blend."},"wd-climb":{"src":"concept:7:words:5:def","route":"#/word/climb","cta":"Open the word card","title":"climb","roman":"KLYM","body":"to go up using your hands and feet","clip":1},"wx-climb":{"src":"concept:7:words:5:ex","route":"#/word/climb","cta":"Open the word card","title":"In a sentence · climb","body":"They climb the hill behind school every spring.","clip":1},"wh-climb":{"src":"concept:7:words:5:hook","route":"#/word/climb","cta":"Open the word card","title":"Remember it · climb","body":"-MB family — the b is silent: clim(b)."},"wd-lamb":{"src":"concept:7:words:6:def","route":"#/word/lamb","cta":"Open the word card","title":"lamb","roman":"LAM","body":"a young sheep","clip":1},"wx-lamb":{"src":"concept:7:words:6:ex","route":"#/word/lamb","cta":"Open the word card","title":"In a sentence · lamb","body":"The lamb followed the farmer everywhere.","clip":1},"wh-lamb":{"src":"concept:7:words:6:hook","route":"#/word/lamb","cta":"Open the word card","title":"Remember it · lamb","body":"Silent b: lam(b), like thumb and comb."},"wd-ghost":{"src":"concept:7:words:7:def","route":"#/word/ghost","cta":"Open the word card","title":"ghost","roman":"GOHST","body":"the spirit of a dead person in stories","clip":1},"wx-ghost":{"src":"concept:7:words:7:ex","route":"#/word/ghost","cta":"Open the word card","title":"In a sentence · ghost","body":"The old house creaked like it had a ghost.","clip":1},"wh-ghost":{"src":"concept:7:words:7:hook","route":"#/word/ghost","cta":"Open the word card","title":"Remember it · ghost","body":"GH up front is not silent here — /g/ + host."},"wd-strong":{"src":"concept:7:words:8:def","route":"#/word/strong","cta":"Open the word card","title":"strong","roman":"STRONG","body":"having great power; not weak","clip":1},"wx-strong":{"src":"concept:7:words:8:ex","route":"#/word/strong","cta":"Open the word card","title":"In a sentence · strong","body":"Strong spellers stretch every blend.","clip":1},"wh-strong":{"src":"concept:7:words:8:hook","route":"#/word/strong","cta":"Open the word card","title":"Remember it · strong","body":"STR blend — all three letters speak, then the NG team."},"wd-island":{"src":"concept:7:words:9:def","route":"#/word/island","cta":"Open the word card","title":"island","roman":"EYE-lund","body":"land with water all around it","clip":1},"wx-island":{"src":"concept:7:words:9:ex","route":"#/word/island","cta":"Open the word card","title":"In a sentence · island","body":"The lighthouse stood on a tiny island.","clip":1},"wh-island":{"src":"concept:7:words:9:hook","route":"#/word/island","cta":"Open the word card","title":"Remember it · island","body":"Silent s — is + land, but say EYE-land."},"wo-island":{"src":"lore:island:0","route":"#/word/island","cta":"Open the word card","title":"Where it comes from · island","body":"Old English igland = water-land, from ig = water/island + land"},"li-u9":{"src":"concept:8:concept","route":"#/stop/u9","cta":"Open this stop","title":"Stress — find the loud beat","body":"Every word with two or more beats has one beat that shouts: ba-NA-na, to-MOR-row, va-CA-tion. Stressed syllables are spelled the way they sound; the quiet ones are where letters hide. Find the loud beat first — then guard the quiet ones."},"lc-u9-0":{"src":"concept:8:cards:0","route":"#/stop/u9","cta":"Open this stop","title":"Stress — find the loud beat · The Core","body":"Say 'banana' three ways: BA-na-na, ba-NA-na, ba-na-NA. Only one sounds right — the middle one. That loud beat is the STRESS, and every long word has exactly one main stress. Your ears already know where it is."},"lc-u9-1":{"src":"concept:8:cards:1","route":"#/stop/u9","cta":"Open this stop","title":"Stress — find the loud beat · Find it fast","body":"Call the word like you’re shouting it across a playground — the syllable you naturally lean on is the stress. Or hum the word: the loudest hum is the stressed beat. va-CA-tion. to-MA-to. mu-SE-um."},"lc-u9-2":{"src":"concept:8:cards:2","route":"#/stop/u9","cta":"Open this stop","title":"Stress — find the loud beat · Loud beats are honest","body":"Stressed syllables say their vowels clearly: the CA in vacation is a clean long a; the MOR in tomorrow is a clear or. Whatever you hear in the loud beat, you can trust — spell it exactly as it sounds."},"lc-u9-3":{"src":"concept:8:cards:3","route":"#/stop/u9","cta":"Open this stop","title":"Stress — find the loud beat · Quiet beats tell lies","body":"Unstressed syllables get mumbled — the first a in 'banana' and the last two sound like lazy 'uh'. That mumble is where spellers slip. Rule: trust the loud beat, double-check every quiet one. (The mumble has a name — meet the schwa, next concept.)"},"lc-u9-4":{"src":"concept:8:cards:4","route":"#/stop/u9","cta":"Open this stop","title":"Stress — find the loud beat · Stress can move","body":"In word families the stress hops around: PHO-to, pho-TOG-ra-phy. When it hops, hidden vowels come out to speak. Can’t hear a vowel in one word? Say its relative — the same letters get loud somewhere else."},"uq-u9-0":{"src":"unit:u9:qs:0","route":"#/stop/u9","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “Stress — find the loud beat”?","opts":["Every word with two or more beats has one beat that shouts: ba-NA-na, to-MOR-row, va-CA-tion.","Old English/Latin un- = not (before adjectives) or reverse the action of (before verbs).","Latin com- = with, together.","The most common suffix in English — from Latin -tionem."],"after":"From “Stress — find the loud beat”."}},"uq-u9-3":{"src":"unit:u9:qs:3","route":"#/stop/u9","cta":"Open this stop","title":"Whose hook?","play":{"q":"“Stress on LI — the quiet -cious tail hides five letters.” — which word is this hook about?","opts":["delicious","banana","tomato","potato"],"after":"From “Stress — find the loud beat”."}},"wd-delicious":{"src":"concept:8:words:0:def","route":"#/word/delicious","cta":"Open the word card","title":"delicious","roman":"dih-LIH-shus","body":"tasting extremely good","clip":1},"wx-delicious":{"src":"concept:8:words:0:ex","route":"#/word/delicious","cta":"Open the word card","title":"In a sentence · delicious","body":"The victory pancakes were delicious.","clip":1},"wh-delicious":{"src":"concept:8:words:0:hook","route":"#/word/delicious","cta":"Open the word card","title":"Remember it · delicious","body":"Stress on LI — the quiet -cious tail hides five letters."},"wd-banana":{"src":"concept:8:words:1:def","route":"#/word/banana","cta":"Open the word card","title":"banana","roman":"buh-NAN-uh","body":"a long curved yellow fruit","clip":1},"wx-banana":{"src":"concept:8:words:1:ex","route":"#/word/banana","cta":"Open the word card","title":"In a sentence · banana","body":"A banana is good brain food before a bee.","clip":1},"wh-banana":{"src":"concept:8:words:1:hook","route":"#/word/banana","cta":"Open the word card","title":"Remember it · banana","body":"Only the middle NA is loud — the other two a’s mumble."},"wo-banana":{"src":"lore:banana:0","route":"#/word/banana","cta":"Open the word card","title":"Where it comes from · banana","body":"Arabic banan = finger, toe; referring to the shape"},"wd-tomato":{"src":"concept:8:words:2:def","route":"#/word/tomato","cta":"Open the word card","title":"tomato","roman":"tuh-MAY-toh","body":"a round red fruit eaten as a vegetable","clip":1},"wx-tomato":{"src":"concept:8:words:2:ex","route":"#/word/tomato","cta":"Open the word card","title":"In a sentence · tomato","body":"She sliced a tomato for the salad.","clip":1},"wh-tomato":{"src":"concept:8:words:2:hook","route":"#/word/tomato","cta":"Open the word card","title":"Remember it · tomato","body":"Stress on MA — to-MA-to, all spelled with plain o’s and a’s."},"wd-potato":{"src":"concept:8:words:3:def","route":"#/word/potato","cta":"Open the word card","title":"potato","roman":"puh-TAY-toh","body":"a starchy vegetable that grows underground","clip":1},"wx-potato":{"src":"concept:8:words:3:ex","route":"#/word/potato","cta":"Open the word card","title":"In a sentence · potato","body":"Baked potato night is Friday night.","clip":1},"wh-potato":{"src":"concept:8:words:3:hook","route":"#/word/potato","cta":"Open the word card","title":"Remember it · potato","body":"po-TA-to — same tune as tomato, stress on the middle."},"wo-potato":{"src":"lore:potato:0","route":"#/word/potato","cta":"Open the word card","title":"Where it comes from · potato","body":"Spanish 'patata' from Taino 'batata' = sweet potato"},"wd-vacation":{"src":"concept:8:words:4:def","route":"#/word/vacation","cta":"Open the word card","title":"vacation","roman":"vay-KAY-shun","body":"time away from school or work to rest or travel","clip":1},"wx-vacation":{"src":"concept:8:words:4:ex","route":"#/word/vacation","cta":"Open the word card","title":"In a sentence · vacation","body":"They visited three national parks on vacation.","clip":1},"wh-vacation":{"src":"concept:8:words:4:hook","route":"#/word/vacation","cta":"Open the word card","title":"Remember it · vacation","body":"The loud CA says long a clearly — va-CA-tion."},"wo-vacation":{"src":"lore:vacation:0","route":"#/word/vacation","cta":"Open the word card","title":"Where it comes from · vacation","body":"Latin vacare = to be free, to be empty"},"wd-tomorrow":{"src":"concept:8:words:5:def","route":"#/word/tomorrow","cta":"Open the word card","title":"tomorrow","roman":"tuh-MOR-oh","body":"the day after today","clip":1},"wx-tomorrow":{"src":"concept:8:words:5:ex","route":"#/word/tomorrow","cta":"Open the word card","title":"In a sentence · tomorrow","body":"Tomorrow is the last practice before the finals.","clip":1},"wh-tomorrow":{"src":"concept:8:words:5:hook","route":"#/word/tomorrow","cta":"Open the word card","title":"Remember it · tomorrow","body":"Stress on MOR — one m in the quiet start, two r’s at the loud middle."},"wd-museum":{"src":"concept:8:words:6:def","route":"#/word/museum","cta":"Open the word card","title":"museum","roman":"myoo-ZEE-um","body":"a building where interesting objects are shown","clip":1},"wx-museum":{"src":"concept:8:words:6:ex","route":"#/word/museum","cta":"Open the word card","title":"In a sentence · museum","body":"The science museum has a giant bee model.","clip":1},"wh-museum":{"src":"concept:8:words:6:hook","route":"#/word/museum","cta":"Open the word card","title":"Remember it · museum","body":"mu-SE-um — the loud ZEE is a plain SE."},"wo-museum":{"src":"lore:museum:0","route":"#/word/museum","cta":"Open the word card","title":"Where it comes from · museum","body":"Greek mouseion = seat of the Muses"},"wd-eleven":{"src":"concept:8:words:7:def","route":"#/word/eleven","cta":"Open the word card","title":"eleven","roman":"ih-LEV-un","body":"the number after ten","clip":1},"wx-eleven":{"src":"concept:8:words:7:ex","route":"#/word/eleven","cta":"Open the word card","title":"In a sentence · eleven","body":"Eleven spellers made it to the final round.","clip":1},"wh-eleven":{"src":"concept:8:words:7:hook","route":"#/word/eleven","cta":"Open the word card","title":"Remember it · eleven","body":"e-LEV-en — trust the loud LEV; the ends mumble."},"wd-gorilla":{"src":"concept:8:words:8:def","route":"#/word/gorilla","cta":"Open the word card","title":"gorilla","roman":"guh-RIL-uh","body":"the largest kind of ape","clip":1},"wx-gorilla":{"src":"concept:8:words:8:ex","route":"#/word/gorilla","cta":"Open the word card","title":"In a sentence · gorilla","body":"The gorilla watched the visitors calmly.","clip":1},"wh-gorilla":{"src":"concept:8:words:8:hook","route":"#/word/gorilla","cta":"Open the word card","title":"Remember it · gorilla","body":"go-RIL-la — loud RIL keeps the twin l’s."},"wo-gorilla":{"src":"lore:gorilla:0","route":"#/word/gorilla","cta":"Open the word card","title":"Where it comes from · gorilla","body":"Greek Gorillai = tribe of hairy women, used by Hanno the explorer; adopted into English via scientific Latin"},"li-u10":{"src":"concept:9:concept","route":"#/stop/u10","cta":"Open this stop","title":"The Sneaky Schwa — the mumbled uh","body":"In quiet syllables, English mumbles every vowel into the same lazy 'uh': the a in about, the o in lemon, the i in pencil. That mumble is the schwa — the #1 spelling trap in the language, because ANY vowel letter can hide behind it."},"lc-u10-0":{"src":"concept:9:cards:0","route":"#/stop/u10","cta":"Open this stop","title":"The Sneaky Schwa — the mumbled uh · The Core","body":"Say 'about'. That first sound is not a clean /a/ — it’s a lazy 'uh'. Say 'lemon' — the o mumbles to 'uh' too. Same mumble, different letters! This shy little sound is the SCHWA, and it lives in almost every long English word."},"lc-u10-1":{"src":"concept:9:cards:1","route":"#/stop/u10","cta":"Open this stop","title":"The Sneaky Schwa — the mumbled uh · Why it is dangerous","body":"The schwa erases the clue. If you hear 'uh', the letter could be A (about), E (taken), I (pencil), O (lemon), or U (circus). Your ears alone cannot pick — which is exactly why quiet syllables cause most misspellings."},"lc-u10-2":{"src":"concept:9:cards:2","route":"#/stop/u10","cta":"Open this stop","title":"The Sneaky Schwa — the mumbled uh · Trick 1: robot voice","body":"Say the word the way it is SPELLED, like a robot: choc-O-late. sep-A-rate. def-I-nite. Champions call this spelling pronunciation. Store the robot voice in your head, and the hidden letter is never hidden again."},"lc-u10-3":{"src":"concept:9:cards:3","route":"#/stop/u10","cta":"Open this stop","title":"The Sneaky Schwa — the mumbled uh · Trick 2: call a relative","body":"Can’t hear the vowel in defin_tion? Call its relative: deFINE — there’s the i, loud and clear. Family words share letters, and the stress moves around the family, so some relative usually shouts the vowel you need."},"lc-u10-4":{"src":"concept:9:cards:4","route":"#/stop/u10","cta":"Open this stop","title":"The Sneaky Schwa — the mumbled uh · Schwa radar","body":"Before spelling a long word, mark the quiet beats — that’s where schwas hide. Loud beats: trust your ears. Quiet beats: use robot voice, call a relative, or ask for the word’s origin. Radar on, trap disarmed."},"uq-u10-0":{"src":"unit:u10:qs:0","route":"#/stop/u10","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “The Sneaky Schwa — the mumbled uh”?","opts":["In quiet syllables, English mumbles every vowel into the same lazy 'uh': the a in about, the o in lemon, the i in pencil.","Latin dis- = apart, not, or deprived of.","Latin malus = bad, evil.","The -ous adjective family means \"full of\" or \"having the quality of.\" Choosing -ious, -eous, or -uous depends on the noun base."],"after":"From “The Sneaky Schwa — the mumbled uh”."}},"uq-u10-1":{"src":"unit:u10:qs:1","route":"#/stop/u10","cta":"Open this stop","title":"Which belongs?","play":{"q":"Which word belongs to this chapter's family?","opts":["chocolate","principal","exquisite","intransigent"],"after":"From “The Sneaky Schwa — the mumbled uh”."}},"uq-u10-3":{"src":"unit:u10:qs:3","route":"#/stop/u10","cta":"Open this stop","title":"Whose hook?","play":{"q":"“Robot voice: choc-O-LATE — the middle o and the a-e are mumbled.” — which word is this hook about?","opts":["chocolate","about","lemon","pencil"],"after":"From “The Sneaky Schwa — the mumbled uh”."}},"wd-chocolate":{"src":"concept:9:words:0:def","route":"#/word/chocolate","cta":"Open the word card","title":"chocolate","roman":"CHOK-lut","body":"a sweet food made from cacao beans","clip":1},"wx-chocolate":{"src":"concept:9:words:0:ex","route":"#/word/chocolate","cta":"Open the word card","title":"In a sentence · chocolate","body":"Hot chocolate is her reward after practice.","clip":1},"wh-chocolate":{"src":"concept:9:words:0:hook","route":"#/word/chocolate","cta":"Open the word card","title":"Remember it · chocolate","body":"Robot voice: choc-O-LATE — the middle o and the a-e are mumbled."},"wo-chocolate":{"src":"lore:chocolate:0","route":"#/word/chocolate","cta":"Open the word card","title":"Where it comes from · chocolate","body":"Nahuatl xocolatl = bitter water"},"wd-about":{"src":"concept:9:words:1:def","route":"#/word/about","cta":"Open the word card","title":"about","roman":"uh-BOWT","body":"concerning; on the subject of","clip":1},"wx-about":{"src":"concept:9:words:1:ex","route":"#/word/about","cta":"Open the word card","title":"In a sentence · about","body":"This chapter is about the sneakiest sound in English.","clip":1},"wh-about":{"src":"concept:9:words:1:hook","route":"#/word/about","cta":"Open the word card","title":"Remember it · about","body":"The opening ‘uh’ is the letter A — a-bout."},"wo-about":{"src":"lore:about:0","route":"#/word/about","cta":"Open the word card","title":"Where it comes from · about","body":"Old English onbutan (around, on the outside of)."},"wd-lemon":{"src":"concept:9:words:2:def","route":"#/word/lemon","cta":"Open the word card","title":"lemon","roman":"LEM-un","body":"a sour yellow fruit","clip":1},"wx-lemon":{"src":"concept:9:words:2:ex","route":"#/word/lemon","cta":"Open the word card","title":"In a sentence · lemon","body":"She squeezed a lemon into her water.","clip":1},"wh-lemon":{"src":"concept:9:words:2:hook","route":"#/word/lemon","cta":"Open the word card","title":"Remember it · lemon","body":"The mumbled ending is O — lem-ON, robot voice: lem-ON."},"wd-pencil":{"src":"concept:9:words:3:def","route":"#/word/pencil","cta":"Open the word card","title":"pencil","roman":"PEN-sul","body":"a writing tool with a graphite center","clip":1},"wx-pencil":{"src":"concept:9:words:3:ex","route":"#/word/pencil","cta":"Open the word card","title":"In a sentence · pencil","body":"Spell it in the air with your pencil first.","clip":1},"wh-pencil":{"src":"concept:9:words:3:hook","route":"#/word/pencil","cta":"Open the word card","title":"Remember it · pencil","body":"The mumble hides an I — pen-CIL."},"wo-pencil":{"src":"lore:pencil:0","route":"#/word/pencil","cta":"Open the word card","title":"Where it comes from · pencil","body":"Latin penicillus = little tail, paintbrush"},"wd-wagon":{"src":"concept:9:words:4:def","route":"#/word/wagon","cta":"Open the word card","title":"wagon","roman":"WAG-un","body":"a four-wheeled cart pulled by hand or horses","clip":1},"wx-wagon":{"src":"concept:9:words:4:ex","route":"#/word/wagon","cta":"Open the word card","title":"In a sentence · wagon","body":"The kids pulled their books in a red wagon.","clip":1},"wh-wagon":{"src":"concept:9:words:4:hook","route":"#/word/wagon","cta":"Open the word card","title":"Remember it · wagon","body":"wag-ON — the quiet o mumbles to uh."},"wd-camera":{"src":"concept:9:words:5:def","route":"#/word/camera","cta":"Open the word card","title":"camera","roman":"KAM-ruh","body":"a device for taking photographs","clip":1},"wx-camera":{"src":"concept:9:words:5:ex","route":"#/word/camera","cta":"Open the word card","title":"In a sentence · camera","body":"The camera flashed when she spelled the winning word.","clip":1},"wh-camera":{"src":"concept:9:words:5:hook","route":"#/word/camera","cta":"Open the word card","title":"Remember it · camera","body":"Robot voice: cam-E-ra — a hidden e lives in the middle."},"wd-animal":{"src":"concept:9:words:6:def","route":"#/word/animal","cta":"Open the word card","title":"animal","roman":"AN-ih-mul","body":"a living creature that can move on its own","clip":1},"wx-animal":{"src":"concept:9:words:6:ex","route":"#/word/animal","cta":"Open the word card","title":"In a sentence · animal","body":"Every animal in the zoo has a name tag.","clip":1},"wh-animal":{"src":"concept:9:words:6:hook","route":"#/word/animal","cta":"Open the word card","title":"Remember it · animal","body":"an-i-MAL — the last a mumbles; robot voice saves it."},"wd-purpose":{"src":"concept:9:words:7:def","route":"#/word/purpose","cta":"Open the word card","title":"purpose","roman":"PUR-pus","body":"the reason something is done","clip":1}});
